// Metrics are derived solely from durable PAPER fills and evidence-backed equity marks.
export function paperStatistics(account){
 const closed=(account.trades||[]).filter(t=>t.side==='SELL'&&Number.isFinite(t.pnlUsd));
 const pnl=closed.map(t=>t.pnlUsd),wins=pnl.filter(x=>x>0).length;
 let peak=account.initialUsd,drawdown=0,drawdownPct=0;
 for(const p of account.balanceHistory||[]){if(!Number.isFinite(p.equityUsd))continue;peak=Math.max(peak,p.equityUsd);drawdown=Math.max(drawdown,peak-p.equityUsd);if(peak>0)drawdownPct=Math.max(drawdownPct,100*(peak-p.equityUsd)/peak);}
 return {tradeCount:account.trades?.length||0,closedTrades:closed.length,winRatePct:closed.length?100*wins/closed.length:null,expectancyUsd:closed.length?pnl.reduce((s,x)=>s+x,0)/closed.length:null,maxDrawdownUsd:drawdown,maxDrawdownPct:drawdownPct,scope:'OBSERVED_PAPER_SESSION_ONLY',profitabilityProven:false};
}
